        [546] = { [2] = "Дозволяє вибраному союзнику ходити по воді протягом {1} хв. Будь-яка шкода скасує ефект.#for {1} min", [3] = "Дозволяє ходити по воді." },
        [547] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 331 },
        [548] = { [2] = "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", ["ref"] = 403 },
        [552] = { [2] = "Намагається вилікувати 1 хворобу на цілі та ще 1 ефект хвороби кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", [3] = "Намагається усунути 1 ефект хвороби кожні {1} с.#every {1} sec" },
