        [568] = { [3] = "Швидкість руху зменшено на {1}%.#by {1}%" },
        [578] = { [2] = "Викликає та відпускає верхового чорного вовка.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [579] = { [2] = "Викликає та відпускає верхового рудого вовка.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [580] = { [2] = "Викликає та відпускає верхового лісового вовка.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [581] = { [2] = "Викликає та відпускає верхового сніжного вовка.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [585] = { [2] = "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}" },
        [586] = { [2] = "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с.#for {1} sec", [3] = "Рівень загрози зменшено." },
        [587] = { [2] = "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min" },
        [588] = { [2] = "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", [3] = "Збільшує броню на {1}.#by {1}" },
        [589] = { [2] = "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec" },
        [591] = { [2] = "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", ["ref"] = 585 },
        [592] = { [2] = "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", [3] = "Поглинає шкоду.", ["ref"] = 17 },
        [594] = { [2] = "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", ["ref"] = 589 },
        [596] = { [2] = "Потужна молитва, що зцілює всім учасникам групи в межах {1} м від {2} до {3} здоров'я.#within {1} yards for {2} to {3}" },
        [597] = { [2] = "Начаклувати паляниці ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} loaves#than {2} min", ["ref"] = 587 },
        [598] = { [2] = "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", ["ref"] = 585 },
        [600] = { [2] = "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", [3] = "Поглинає шкоду.", ["ref"] = 17 },
        [602] = { [2] = "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", [3] = "Збільшує броню на {1}.#by {1}", ["ref"] = 588 },
        [604] = { [2] = "Послаблює магію на обраному учаснику групи, зменшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", [3] = "Зменшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}" },
        [605] = { [2] = "Бере під контроль розум гуманоїда не вище {1} рівня, але збільшує інтервал між його атаками на {2}%. Триває до {3} хв.#up to level {1}#attacks by {2}%#Lasts up to {3} min", [3] = "Причаровано. Інтервал між атаками збільшено на {1}%.#by {1}%" },
        [633] = { [2] = "Зцілює дружню ціль на значення, що дорівнює максимальному запасу здоров'я паладина. Витрачає весь залишок мани паладина при використанні." },
        [635] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}" },
        [639] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 635 },
        [642] = { [2] = "Захищає паладина від будь-якої шкоди та заклять на {1} с, але [збільшує інтервал між вашими атаками на {1}%#time between your attacks by {1}%][зменшує всю вашу шкоду на {1}%#reduces all damage you deal by {1}%]. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", [3] = "Невразливість до всіх атак і заклять, але [інтервал між атаками збільшено на {1}%#time between your attacks by {1}%][всю завдану шкоду зменшено на {1}%#all damage you deal by {1}%]." },
        [643] = { [2] = "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", [3] = "Збільшує броню на {1}.#by {1}", ["ref"] = 465 },
        [647] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 635 },
        [674] = { [2] = "Дозволяє брати в ліву руку одноручну зброю або зброю для лівої руки." },
        [676] = { [2] = "Роззброює ворога на {1} с.#for {1} sec", [3] = "Роззброєно!" },
        [686] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню." },
        [687] = { [2] = "Захищає заклинача, збільшуючи броню на {1} та відновлюючи {2} здоров'я кожні {3} с протягом {4} хв.#armor by {1} and restores {2} Health per {3} sec. for {4} min", [3] = "Збільшує броню на {1} та відновлює {2} здоров'я кожні {3} с.#armor by {1} and restores {2} Health per {3} sec" },
        [688] = { [2] = "Викликає біса, підкореного чорнокнижникові." },
        [689] = { [2] = "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", [3] = "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health" },
        [690] = { [2] = "Завдає цілі від {1} до {2} шкоди вогнем.#for {1} to {2} Fire" },
        [691] = { [2] = "Викликає скверногончу, підкорену чорнокнижникові." },
        [694] = { [2] = "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", [3] = "Спровоковано." },
        [695] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", ["ref"] = 686 },
        [696] = { [2] = "Захищає заклинача, збільшуючи броню на {1} та відновлюючи {2} здоров'я кожні {3} с протягом {4} хв.#armor by {1} and restores {2} Health per {3} sec. for {4} min", [3] = "Збільшує броню на {1} та відновлює {2} здоров'я кожні {3} с.#armor by {1} and restores {2} Health per {3} sec", ["ref"] = 687 },
        [697] = { [2] = "Викликає пустотника, підкореного чорнокнижникові." },
        [698] = { [2] = "Починає ритуал, що викликає обраного учасника групи. Для завершення ритуалу потрібна допомога 2 учасників групи. Щоб узяти участь у ритуалі, усі гравці повинні бути поза боєм, натиснути правою кнопкою миші на портал і не рухатися до завершення ритуалу." },
        [699] = { [2] = "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", [3] = "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", ["ref"] = 689 },
        [700] = { [2] = "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", [3] = "Спить." },
        [701] = { [2] = "Завдає цілі {1} шкоди вогнем.#for {1} Fire" },
        [702] = { [2] = "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", [3] = "Фізичну шкоду зменшено на {1}.#by {1}" },
        [703] = { [2] = "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", [3] = "{1} шкоди кожні {2} с.#{1} damage every {2} sec" },
        [704] = { [2] = "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", [3] = "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}" },
        [705] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", ["ref"] = 686 },
        [706] = { [2] = "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", [3] = "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec" },
        [707] = { [2] = "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", [3] = "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", ["ref"] = 348 },
        [709] = { [2] = "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", [3] = "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", ["ref"] = 689 },
        [710] = { [2] = "Виганяє ворожу ціль до іншого виміру, перешкоджаючи всім її діям, але при цьому робить її невразливою протягом {1} с. Одночасно лише одна ціль може бути вигнаною. Діє лише на демонів та елементалів.#for up to {1} sec", [3] = "Невразливість, але неможливо виконувати будь-які дії." },
        [712] = { [2] = "Викликає сукуба, підкореного чорнокнижникові." },
        [713] = { [2] = "Викликає інкуба, підкореного чорнокнижникові." },
        [720] = { [3] = "Обплетено" },
        [724] = { [2] = "Створює священний колодязь світла біля жерця. Учасники вашої групи чи рейду можуть випити з нього щоб відновити {1} здоров'я протягом {2} с. Будь-яка отримана шкода знімає цей ефект. Колодязь існує {3} хв або до {4} застосувань.#restore {1} health over {2} sec#lasts for {3} min or {4} charges" },
        [731] = { [3] = "Обплетено", ["ref"] = 720 },
        [740] = { [2] = "Відновлює всім учасникам групи неподалік {1} здоров'я кожні {2} с протягом {3} с. Друїд має підтримувати закляття.#for {1} every {2} seconds for {3} sec", [3] = "Зцілює учасникам групи неподалік {1} здоров'я кожні {2} с.#for {1} every {2} sec" },
        [744] = { [2] = "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", [3] = "Завдає шкоди від природи кожні {1} с.#every {1} sec" },
        [746] = { [2] = "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", [3] = "Відновлення {1} здоров'я щосекунди.#Healing {1} damage" },
        [755] = { [2] = "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", [3] = "Передає здоров'я." },
        [759] = { [2] = "Начаклувати маноагат, який можна використати для миттєвого відновлення від {1} до {2} мани.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на 15 хвилин.#restore {1} to {2}" },
        [768] = { [2] = "Набути котячої подоби, що збільшує силу атаки ближнього бою на {1} плюс показник спритності. Також захищає заклинача від ефектів поліморфії та дозволяє використання котячих здібностей.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#power by {1} plus", [3] = "Невразливість до ефектів поліморфії. Збільшує силу атаки ближнього бою на {1} плюс показник спритності.#power by {1} plus" },
        [769] = { [2] = "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage" },
        [770] = { [2] = "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", [3] = "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}" },
        [772] = { [2] = "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", [3] = "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec" },
        [774] = { [2] = "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", [3] = "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec" },
        [778] = { [2] = "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", [3] = "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", ["ref"] = 770 },
        [779] = { [2] = "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", ["ref"] = 769 },
        [780] = { [2] = "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", ["ref"] = 769 },
        [781] = { [2] = "Провести спробу відступити від цілі, зменшуючи загрозу. Персонаж виходить з бою." },
        [782] = { [2] = "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", [3] = "Завдає {1} шкоди від природи нападникам.#Causes {1}", ["ref"] = 467 },
        [783] = { [2] = "Набути мандрівної подоби, що збільшує швидкість руху на {1}%. Також захищає заклинача від ефектів поліморфії. Можна використовувати лише просто неба.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#speed by {1}%", [3] = "Невразливість до ефектів поліморфії. Швидкість руху збільшено на {1}%.#by {1}%" },
        [785] = { [3] = "Причаровано.\nШкоду збільшено на {1}%.\nЗакляття вимовляються миттєво.\nВсі опори збільшено на {2}.\nШвидкість руху збільшено на {3}%.#Damage increased by {1}%#resistances increased by {2}#speed increased by {3}%" },
        [806] = { [2] = "Збільшує силу на {1} та завдає вам {2} шкоди кожні {3} с протягом {4} хв.#by {1} and does {2} damage to you every {3} sec for {4} min", [3] = "Силу збільшено. Отримання періодичної шкоди." },
        [812] = { [2] = "Періодично застосовує спалення мани.", [3] = "Періодично застосовує спалення мани." },
        [818] = { [2] = "Розпалити вогнище, яке дозволяє готувати їжу та підвищує дух навколишніх персонажів на {1}.#those nearby by {1} and" },
        [833] = { [2] = "Миттєво відновлює {1} здоров'я. Також відновлює {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі.#heals {1} damage#restores {2} mana over {3} sec", [3] = "Відновлює {1} мани щосекунди.#Restores {1} mana" },
        [834] = { [2] = "Збільшує броню на {1} протягом {2} год.#by {1} for {2} h", [3] = "Броню збільшено на {1}.#by {1}" },
        [835] = { ["ref"] = 56 },
        [837] = { [2] = "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%", ["ref"] = 116 },
        [845] = { [2] = "Розмашиста атака, що завдає шкоди зброєю плюс {1} по цілі та по найближчому до неї ворогу.#damage plus {1} to" },
        [853] = { [2] = "Приголомшує ціль на {1} с.#for {1} sec", [3] = "Приголомшено." },
        [865] = { [2] = "Вражає ворогів поруч із заклиначем, завдаючи [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди кригою, та приморожує їх на місці на {1} с. Подальше завдання шкоди може перервати дію цього ефекту.#up to {1} sec", [3] = "Приморожено.", ["ref"] = 122 },
        [871] = { [2] = "Зменшує отриману шкоду від атак ближнього бою, дальнього бою та заклять на {1}% протягом {2} с.#by {1}% for {2} sec", [3] = "Отриману шкоду зменшено на {1}%.#reduced by {1}%" },
        [879] = { [2] = "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy" },
        [883] = { [2] = "Викликає вашого вихованця." },
        [905] = { [2] = "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", [3] = "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", ["ref"] = 324 },
        [913] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 331 },
        [915] = { [2] = "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", ["ref"] = 403 },
        [921] = { [2] = "Обнишпорити кишені цілі." },
        [930] = { [2] = "Кидає в ціль блискавку, що завдає від {1} до {2} шкоди від природи та перестрибує на інших ворогів неподалік. Кожен стрибок завдає на {3}% менше шкоди. Вражає до {4} цілей.#dealing {1} to {2}#damage by {3}#{4} total targets.", ["ref"] = 421 },
        [939] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 331 },
        [943] = { [2] = "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", ["ref"] = 403 },
        [945] = { [2] = "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", [3] = "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", ["ref"] = 324 },
        [959] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 331 },
        [970] = { [2] = "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", ["ref"] = 589 },
        [976] = { [2] = "Збільшує опір цілі до тіні на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Опір тіні збільшено на {1}.#by {1}" },
        [982] = { [2] = "Оживляє вашого вихованця, повертаючи його до життя з {1}% здоров'я.#with {1}%" },
        [984] = { [2] = "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", ["ref"] = 585 },
        [988] = { [2] = "Розвіює магію з цілі, знімаючи 2 негативні ефекти з союзника або 2 сприятливі ефекти з ворога." },
        [990] = { [2] = "Начаклувати житній хліб ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} loaves#than {2} min", ["ref"] = 587 },
        [992] = { [2] = "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", ["ref"] = 589 },
        [996] = { [2] = "Потужна молитва, що зцілює всім учасникам групи в межах {1} м від {2} до {3} здоров'я.#within {1} yards for {2} to {3}", ["ref"] = 596 },
        [1002] = { [2] = "Узяти безпосередній контроль над вашим вихованцем і бачити його очима протягом {1} хв.#for {1} min", [3] = "Безпосередній контроль вихованця." },
        [1004] = { [2] = "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", ["ref"] = 585 },
        [1006] = { [2] = "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", [3] = "Збільшує броню на {1}.#by {1}", ["ref"] = 588 },
        [1008] = { [2] = "Підсилює магію на обраному учаснику групи, збільшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", [3] = "Збільшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}" },
        [1020] = { [2] = "Захищає паладина від будь-якої шкоди та заклять на {1} с, але [збільшує інтервал між вашими атаками на {1}%#time between your attacks by {1}%][зменшує всю вашу шкоду на {1}%#reduces all damage you deal by {1}%]. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", [3] = "Невразливість до всіх атак і заклять, але [інтервал між атаками збільшено на {1}%#time between your attacks by {1}%][всю завдану шкоду зменшено на {1}%#all damage you deal by {1}%].", ["ref"] = 642 },
        [1022] = { [2] = "Захищає обраного учасника групи від усіх фізичних атак на {1} с, але протягом цього часу ціль не може атакувати чи використовувати фізичні здібності. Гравці можуть мати лише одне благословення від кожного паладина одночасно. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" повторно протягом {2} хв.#attacks for {1} sec#again for {2} min", [3] = "Невразливість до фізичних атак. Не може атакувати чи використовувати фізичні здібності." },
        [1026] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 635 },
        [1032] = { [2] = "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", [3] = "Збільшує броню на {1}.#by {1}", ["ref"] = 465 },
        [1038] = { [2] = "Благословляє учасника групи, зменшуючи його загрозу на {1}% протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1}% for {2} min", [3] = "Зменшує загрозу на {1}%.#by {1}%" },
        [1042] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", ["ref"] = 635 },
        [1044] = { [2] = "Благословляє дружню ціль, надаючи невразливість до ефектів обмеження руху на {1} с. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#for {1} sec", [3] = "Невразливість до ефектів обмеження руху." },
        [1058] = { [2] = "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", [3] = "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", ["ref"] = 774 },
        [1062] = { [2] = "Приковує ціль на місці та завдає {1} шкоди від природи протягом {2} с. Подальша завдана шкода може перервати дію ефекту. Можна використовувати лише просто неба.#causes {1}#over {2} sec", [3] = "Приковано. Завдає {1} шкоди від природи кожні {2} с.#Causes {1}#every {2} sec", ["ref"] = 339 },
        [1064] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я та перестрибує на інші цілі неподалік. Якщо закляття було націлене на учасника групи, подальші стрибки переходитимуть лише на інших її учасників. Кожен наступний стрибок зцілює на {3}% менше здоров'я. Зцілює до {4} цілей.#for {1} to {2}#{3}% as effective#Heals {4} total" },
        [1066] = { [2] = "Набути водної подоби, що збільшує швидкість плавання на {1}% та дозволяє дихати під водою. Також захищає заклинача від ефектів поліморфії.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#speed by {1}%", [3] = "Невразливість до ефектів поліморфії. Збільшує швидкість плавання на {1}% та дозволяє дихати під водою.#speed by {1}%" },
        [1075] = { [2] = "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", [3] = "Завдає {1} шкоди від природи нападникам.#Causes {1}", ["ref"] = 467 },
        [1079] = { [2] = "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", [3] = "Шкода від кровотечі кожні {1} с.#every {1} sec" },
        [1082] = { [2] = "Дряпає ворога, завдаючи {1} додаткової шкоди. Збільшує довжину комбінації на {2} прийом.#causing {1}#{2} combo" },
        [1084] = { ["ref"] = 690 },
        [1086] = { [2] = "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", [3] = "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", ["ref"] = 706 },
        [1088] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", ["ref"] = 686 },
        [1090] = { [2] = "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", [3] = "Спить.", ["ref"] = 700 },
        [1094] = { [2] = "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", [3] = "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", ["ref"] = 348 },
        [1096] = { ["ref"] = 690 },
        [1098] = { [2] = "Поневолює обраного демона до {1} рівня, примушуючи його підкоритися вам. Протягом дії поневолення інтервал між атаками демона збільшується на {2}%, а його вимова заклять сповільнюється на {3}%. Триває до {4} хв. Якщо ви знову поневолюватимете одного й того ж демона, його буде важче контролювати з кожною наступною спробою.#up to level {1}#increased by {2}%#slowed by {3}%#up to {4} min", [3] = "Поневолено." },
        [1106] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", ["ref"] = 686 },
        [1108] = { [2] = "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", [3] = "Фізичну шкоду зменшено на {1}.#by {1}", ["ref"] = 702 },
        [1120] = { [2] = "Висмоктує душу з цілі, завдаючи {1} шкоди тінню протягом {2} с. Якщо ціль під час цього помирає та приносить досвід або честь, заклинач отримує уламок душі. Уламки душі потрібні для інших заклять.#causing {1}#over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2}" },
        [1121] = { [3] = "Обплетено", ["ref"] = 720 },
        [1122] = { [2] = "Викликає метеорит з Підсвітньої Крутоверті, що завдає {1} шкоди вогнем і приголомшує всі ворожі цілі в місці падіння на {2} с. З кратера підіймається пекельник, підкорений заклиначеві на {3} хв. Після закінчення цього часу пекельника потрібно поневолити, щоб продовжити керувати ним. Можна використовувати лише просто неба.#causing {1} Fire#area for {2} sec#caster for {3} min" },
        [1126] = { [2] = "Збільшує броню дружньої цілі на {1} на {2} хв.#armor by {1} for {2} min", [3] = "Збільшує броню на {1}.#armor by {1}" },
        [1127] = { [2] = "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", [3] = "Відновлює {1} здоров'я щосекунди.#Restores {1} health", ["ref"] = 433 },
        [1129] = { [2] = "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", [3] = "Відновлює {1} здоров'я щосекунди.#Restores {1} health", ["ref"] = 433 },
        [1130] = { [2] = "Відмічає ціль мисливською міткою, збільшуючи силу атаки дальнього бою всіх нападників проти відміченої цілі на {1}. Окрім того мисливець завжди бачить відмічену ціль, навіть якщо та стає непомітною або невидимою. Ціль також відображається на мінімапі. Триває {2} хв.#target by {1}#Lasts for {2} min", [3] = "Всі нападники отримують додатково {1} сили атаки дальнього бою проти цієї цілі.#gain {1} Ranged" },
        [1131] = { [2] = "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", [3] = "Відновлює {1} здоров'я щосекунди.#Restores {1} health", ["ref"] = 433 },
        [1133] = { [2] = "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", [3] = "Відновлює {1} мани щосекунди.#Restores {1} mana", ["ref"] = 430 },
        [1135] = { [2] = "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", [3] = "Відновлює {1} мани щосекунди.#Restores {1} mana", ["ref"] = 430 },
        [1137] = { [2] = "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", [3] = "Відновлює {1} мани щосекунди.#Restores {1} mana", ["ref"] = 430 },
        [1138] = { [2] = "Збільшує опір кризі та тіні на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Опір кризі та тіні збільшено." },
        [1139] = { [2] = "Збільшує інтервал між атаками цілі на {1}% протягом {2} с.#by {1}% for {2} sec", [3] = "Швидкість атак зменшено." },
        [1152] = { [2] = "Очищує дружню ціль, знімаючи 1 ефект хвороби та 1 ефект отруєння." },
        [1159] = { [2] = "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", [3] = "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", ["ref"] = 746 },
        [1160] = { [2] = "Зменшує силу атаки ближнього бою всіх ворогів в межах {1} м на {2} протягом {3} с.#within {1} yards by {2} for {3} sec", [3] = "Зменшує силу атаки ближнього бою на {1}.#power by {1}" },
        [1161] = { [2] = "Змушує всіх ворогів навколо атакувати вас протягом {1} с.#for {1} sec", [3] = "Спровоковано." },
        [1208] = { },
        [1243] = { [2] = "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Збільшує витривалість на {1}.#by {1}" },
        [1244] = { [2] = "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Збільшує витривалість на {1}.#by {1}", ["ref"] = 1243 },
        [1245] = { [2] = "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Збільшує витривалість на {1}.#by {1}", ["ref"] = 1243 },
        [1329] = { [2] = "Миттєва атака зброєю в обох руках, що завдає {1}% та додатково {2} шкоди від кожної зброї. Шкода збільшується на {3}% проти отруєних цілей. Збільшує довжину комбінації на {4} прийоми.#weapons for {1}% weapon#additional {2} with each#by {3}% against Poisoned#Awards {4} combo" },
        [1386] = { [3] = "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%" },
        [1430] = { [2] = "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", [3] = "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", ["ref"] = 774 },
        [1449] = { [2] = "Створює вибух арканічної магії навколо заклинача, завдаючи від {1} до {2} шкоди арканою всім цілям у радіусі {3} м.#causing {1} to {2}#within {3} yards" },
        [1454] = { [2] = "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana" },
        [1455] = { [2] = "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana", ["ref"] = 1454 },
        [1456] = { [2] = "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana", ["ref"] = 1454 },
        [1459] = { [2] = "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", [3] = "Збільшує інтелект на {1}.#by {1}" },
        [1460] = { [2] = "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", [3] = "Збільшує інтелект на {1}.#by {1}", ["ref"] = 1459 },
        [1461] = { [2] = "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", [3] = "Збільшує інтелект на {1}.#by {1}", ["ref"] = 1459 },
        [1462] = { [2] = "Збирає інформацію про вибраного звіра. Підказка відобразить шкоду, здоров'я, броню, особливі опори та дієту.", [3] = "Знання виявлено." },
        [1463] = { [2] = "Поглинає {1} фізичної шкоди за рахунок мани. Випалює {2} мани за кожну одиницю поглинутої шкоди. Триває {3} хв.#Absorbs {1} physical#Drains {2} mana#Lasts {3} min", [3] = "Поглинає фізичну шкоду за рахунок мани." },
        [1464] = { [2] = "Трощить ворога, завдаючи шкоди зброєю плюс {1}.#damage plus {1}" },
        [1490] = { [2] = "Проклинає ціль на {1} хв, зменшуючи опір вогню та кризі на {2} і збільшуючи отриману шкоду від вогню та криги на {3}%. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#for {1} min#resistances by {2}#taken by {3}", [3] = "Зменшує опір вогню та кризі на {1}. Збільшує отриману шкоду від вогню та криги на {2}%.#resistances by {1}#taken by {2}" },
        [1494] = { [2] = "Відображає на мінімапі місцезнаходження звірів неподалік. Одночасно можна вистежувати лише щось одне.", [3] = "Вистежування звірів." },
        [1495] = { [2] = "Контратакує ворога, завдаючи {1} шкоди. Можна виконати лише після того, як ви ухилилися.#for {1} damage" },
        [1499] = { [2] = "Встановити крижану пастку, яка заморозить першого ворога при наближенні та унеможливить всі його дії впродовж {1} с. Будь-яка шкода розіб'є лід. Пастка існуватиме {2} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#action for up to {1} sec#exist for {2} min" },
        [1510] = { [2] = "Безперервно обстрілює вибране місце, завдаючи {1} шкоди від аркани ворожим цілям в межах {2} м щосекунди протягом {3} с.#causing {1}#within {2} y#for {3} sec" },
        [1513] = { [2] = "Відлякує звіра, змушуючи його тікати з переляку протягом {1} с. Завдана шкода може перервати ефект. Одночасно лише один звір може бути наляканим.#for up to {1} sec", [3] = "Налякано." },
        [1515] = { [2] = "Почати приручення звіра, який стане вашим супутником. Ваша броня знижується на {1}%, поки ви зосереджуєтеся на процесі приручення звіра протягом {2} с. Якщо ви втратите увагу звіра з будь-якої причини, процес приручення провалиться. Після приручення, звір буде дуже нещасливим та недовірливим. Спробуйте одразу погодувати вихованця, щоб зробити його щасливим.#by {1}%#for {2} sec", [3] = "Приручення вихованця." },
        [1535] = { [2] = "Викликає тотем вогненного спалаху з {1} здоров'я на {2} с. Якщо тотем не буде знищено за {3} с, він завдасть від {4} до {5} шкоди вогнем усім ворогам в межах {6} м.#has {1} health and lasts {2} sec#within {3} sec#inflicts {4} to {5}#within {6} y" },
        [1539] = { [3] = "Збільшує щастя." },
        [1543] = { [2] = "Викриває всіх прихованих та невидимих ворогів в межах {1} м від вибраного місця протягом {2} с.#within {1} y#for {2} sec", [3] = "Виявлення прихованих та невидимих істот." },
        [1604] = { [3] = "Швидкість руху зменшено на {1}%.#by {1}%" },
        [1608] = { [2] = "Сильна атака, що збільшує шкоду ближнього бою на {1} і спричиняє високий рівень загрози.#damage by {1}", ["ref"] = 78 },
        [1671] = { [2] = "Удар цілі щитом, що завдає {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", ["ref"] = 72 },
        [1672] = { [2] = "Удар цілі щитом, що завдає {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", ["ref"] = 72 },
        [1680] = { [2] = "Ви атакуєте до {1} ворогів в межах {2} м сталевим вихром, завдаючи шкоди зброєю кожному ворогу.#up to {1} enemies within {2} yards" },
        [1706] = { [2] = "Дозволяє заклиначу левітувати, плинучи невисоко над землею. Під час левітації ви падатимете зі зниженою швидкістю та зможете ходити по воді. Будь-яка шкода скасує цей ефект. Триває {1} хв.#Lasts {1} min", [3] = "Левітує." },
        [1714] = { [2] = "Примушує ціль говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}%. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі. Триває {2} с.#by {1}%#Lasts {2} sec", [3] = "Говорить мовою демонів, що збільшує час вимови заклять на {1}%.#by {1}%" },
        [1715] = { [2] = "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%" },
        [1719] = { [2] = "[Воїн буде завдавати критичних ударів більшістю своїх атак та#cause critical hits with most attacks][Ймовірність критичного удару збільшиться на {1}%, а воїн#will gain {1}% increased critical strike chance] отримає невразливість до ефектів страху протягом {1} с, але отримана шкода збільшиться на {2}%.#next {1} sec#increased by {2}", [3] = "Невразливість до ефектів страху, більшість атак завдають критичних ударів[, але отриману шкоду збільшено на {1}%#damage taken is increased by {1}%]." },
        [1725] = { [2] = "Метнути приманку, що відволіче увагу всіх ворогів поблизу на {1} с. Не порушує непомітності.#for {1} sec" },
        [1735] = { [2] = "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", [3] = "Силу атаки ближнього бою зменшено на {1}.#power by {1}", ["ref"] = 99 },
        [1742] = { [2] = "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас." },
        [1752] = { [2] = "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo" },
        [1753] = { [2] = "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", ["ref"] = 1742 },
        [1754] = { [2] = "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", ["ref"] = 1742 },
        [1755] = { [2] = "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", ["ref"] = 1742 },
        [1756] = { [2] = "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", ["ref"] = 1742 },
        [1757] = { [2] = "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", ["ref"] = 1752 },
        [1758] = { [2] = "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", ["ref"] = 1752 },
        [1759] = { [2] = "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", ["ref"] = 1752 },
        [1760] = { [2] = "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", ["ref"] = 1752 },
        [1766] = { [2] = "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec" },
        [1767] = { [2] = "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", ["ref"] = 1766 },
        [1768] = { [2] = "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", ["ref"] = 1766 },
        [1769] = { [2] = "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", ["ref"] = 1766 },
        [1776] = { [2] = "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", [3] = "Недієздатність." },
        [1777] = { [2] = "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", [3] = "Недієздатність.", ["ref"] = 1776 },
        [1784] = { [2] = "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", [3] = "Непомітність. Рух сповільнено на {1}%.#by {1}%" },
        [1785] = { [2] = "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", [3] = "Непомітність. Рух сповільнено на {1}%.#by {1}%", ["ref"] = 1784 },
        [1786] = { [2] = "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", [3] = "Непомітність. Рух сповільнено на {1}%.#by {1}%", ["ref"] = 1784 },
        [1787] = { [2] = "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", [3] = "Непомітність. Рух сповільнено на {1}%.#by {1}%", ["ref"] = 1784 },
        [1804] = { [2] = "Дозволяє відкривати замкнені скрині та двері." },
        [1822] = { [2] = "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", [3] = "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec" },
        [1823] = { [2] = "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", [3] = "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", ["ref"] = 1822 },
        [1824] = { [2] = "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", [3] = "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", ["ref"] = 1822 },
        [1833] = { [2] = "Приголомшує ціль на {1} с. Необхідно перебувати в непомітності. Збільшує довжину комбінації на {2} прийоми.#for {1} sec#{2} combo", [3] = "Приголомшено." },
        [1842] = { [2] = "Підкрастися до пастки та знешкодити її. Не наближайтеся занадто близько, інакше пастка спрацює." },
        [1850] = { [2] = "Збільшує швидкість руху на {1}% протягом {2} с. Не перериває дію здібності \"Зачаїтися\".#speed by {1}% for {2} sec", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [1853] = { [2] = "Провокує ціль, збільшуючи ймовірність того, що вона зосередить свої атаки на вас.", ["ref"] = 2649 },
        [1856] = { [2] = "Дозволяє пройдисвіту зникнути з поля зору ворогів, увійшовши в стан покращеної непомітності на {1} с. Також знімає всі ефекти обмеження руху.#for {1} sec", [3] = "Покращена непомітність." },
        [1857] = { [2] = "Дозволяє пройдисвіту зникнути з поля зору ворогів, увійшовши в стан покращеної непомітності на {1} с. Також знімає всі ефекти обмеження руху. Дієвіше за \"Зникнення\" (Ранг {2}).#for {1} sec#(Rank {2})", [3] = "Покращена непомітність.", ["ref"] = 1856 },
        [1860] = { [2] = "Зменшує шкоду від падіння." },
        [1906] = { [2] = "Ривок у ворога, що сповільнює його рух на {1} с.#for {1} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%" },
        [1940] = { [2] = "Завдає від {1} до {2} шкоди вогнем в радіусі {3} м.#Inflicts {1} to {2} Fire#a {3} yard" },
        [1943] = { [2] = "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", [3] = "{1} шкоди кожні {2} с.#{1} damage every {2} sec" },
        [1949] = { [2] = "Підпалює землю навколо заклинача, щосекунди завдаючи {1} шкоди вогнем йому та {2} шкоди вогнем усім ворогам поблизу. Триває {3} с.#causing {1}#and {2}#Lasts {3} sec", [3] = "Завдає шкоди собі та всім навколишнім ворогам." },
        [1953] = { [2] = "Телепортує заклинача на {1} м уперед, якщо на шляху немає перешкод. Також звільняє від приголомшень та пут.#caster {1} yards", [3] = "Блимає." },
        [1966] = { [2] = "Виконує оманливий випад, що не завдає шкоди та трохи зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас." },
        [1978] = { [2] = "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", [3] = "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec" },
        [2006] = { [2] = "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana" },
        [2008] = { [2] = "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana" },
        [2010] = { [2] = "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", ["ref"] = 2006 },
        [2018] = { [2] = "Дозволяє виготовляти просту зброю і обладунки та розвивати навичку до 75 рівня. Потребує каміння й металу, які можна знайти за допомогою гірництва." },
        [2023] = { [2] = "Відновлює [{1}#Restores {1} mana.][від {1} до {2}#Restores {1} to {2} mana.] мани.", ["ref"] = 436 },
        [2024] = { [2] = "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", ["ref"] = 439 },
        [2050] = { [2] = "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}" },
        [2052] = { [2] = "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", ["ref"] = 2050 },
        [2053] = { [2] = "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", ["ref"] = 2050 },
        [2054] = { [2] = "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}" },
        [2055] = { [2] = "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", ["ref"] = 2054 },
        [2060] = { [2] = "Повільне закляття, що зцілює одній цілі від {1} до {2} здоров'я.#for {1} to {2}" },
        [2061] = { [2] = "Зцілює дружній цілі від {1} до {2} здоров'я.#target for {1} to {2}" },
        [2070] = { [2] = "Робить ціль недієздатною на {1} с. Необхідно перебувати в непомітності. Діє лише проти гуманоїдів, що перебувають поза боєм. Будь-яка шкода знімає ефект з ураженої цілі. Одночасно лише 1 ціль може бути оглушеною.#up to {1} sec", [3] = "Недієздатність." },
        [2090] = { [2] = "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", [3] = "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", ["ref"] = 774 },
        [2091] = { [2] = "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", [3] = "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", ["ref"] = 774 },
        [2094] = { [2] = "Засліплює ціль, змушуючи її блукати протягом {1} с. Будь-яка шкода перериває дію ефекту.#for up to {1} sec", [3] = "Дезорієнтовано." },
        [2096] = { [2] = "Дозволяє заклиначу бачити очима цілі протягом {1} хв.#for {1} min", [3] = "Здатність бачити очима цілі." },
        [2098] = { [2] = "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}" },
        [2108] = { [2] = "Дозволяє виготовляти шкіряні обладунки та розвивати навичку до 75 рівня. Потребує обрізків шкіри та шкур, які можна зібрати за допомогою навички шкуродерства." },
        [2120] = { [2] = "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", [3] = "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec" },
        [2121] = { [2] = "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", [3] = "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2}", ["ref"] = 2120 },
        [2136] = { [2] = "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}" },
        [2137] = { [2] = "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", ["ref"] = 2136 },
        [2138] = { [2] = "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", ["ref"] = 2136 },
        [2139] = { [2] = "Протидіє вимові закляття ворогом, унеможливлюючи вимову будь-яких інших заклять тієї ж школи магії протягом {1} с. Спричиняє високий рівень загрози.#cast for {1} sec" },
        [2147] = { [2] = "Періодичне зцілення", [3] = "Зцілює {1} здоров'я кожні {2} с.#for {1} every {2} sec" },
        [2148] = { [2] = "Періодично застосовує Тіньовий шторм.", [3] = "Періодично застосовує Тіньовий шторм." },
        [2259] = { [2] = "Дозволяє варити прості зілля та розвивати навичку до 75 рівня. Потребує трав, які можна знайти за допомогою травництва." },
        [2362] = { [2] = "Створює камінь чарів для заклинача. При спорядженні та використанні цей камінь чарів усуває всі магічні ефекти із заклинача та поглинає {1} магічної шкоди протягом {2} хв. Також при спорядженні цей камінь чарів збільшує ваш шанс завдання критичного удару закляттями на {3}%.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {4} хв.#absorb {1}#for {2} min#spells by {3}#than {4} min" },
        [2367] = { [2] = "Збільшує силу на {1} протягом {2} год.#by {1} for {2} h", [3] = "Силу збільшено на {1}.#by {1}" },
        [2370] = { [2] = "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я." },
        [2374] = { [2] = "Збільшує спритність на {1} протягом {2} год.#by {1} for {2} h", [3] = "Спритність збільшено на {1}.#by {1}" },
        [2376] = { [2] = "Збільшує інтелект на {1} протягом {2} год.#by {1} for {2} h", [3] = "Інтелект збільшено на {1}.#by {1}" },
        [2378] = { [2] = "Збільшує запас здоров'я на {1} протягом {2} год.#by {1} for {2} h", [3] = "Запас здоров'я збільшено на {1}.#by {1}" },
        [2379] = { [2] = "Збільшує швидкість бігу на {1}% протягом {2} с.#by {1}% for {2} sec", [3] = "Швидкість бігу збільшено на {1}%.#by {1}%" },
        [2380] = { [2] = "Збільшує ваш опір всім школам магії на {1} протягом {2} хв.#by {1} for {2} min", [3] = "Опір магії збільшено." },
        [2383] = { [2] = "На мінікарті з'являються мітки кущів з травами неподалік. Одночасно можна відстежувати лише щось одне.", [3] = "Шукає трави." },
        [2457] = { [2] = "Збалансована бойова стійка." },
        [2458] = { [2] = "Агресивна стійка. Збільшує ймовірність завдання критичного удару на {1}%, а всю отриману шкоду на {2}%.#chance is increased by {1}#taken is increased by {2}" },
        [2479] = { [3] = "Наразі ви не приносите жодних очок честі ворогам." },
        [2481] = { [2] = "Дозволяє дворфу відчувати скарби неподалік, відмічаючи їх на мінімапі. Триває до відміни.", [3] = "Пошук скарбів." },
        [2484] = { [2] = "Викликає тотем земного зв'язування з {1} здоров'я на {2} с. Тотем сповільнює рух ворогів в межах {3} м.#with {1} health#for {2} sec#within {3} y" },
        [2537] = { [2] = "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", [3] = "Збільшує отриману шкоду святістю на {1}.#up to {1}" },
        [2550] = { [2] = "Дозволяє готувати базові страви та розвивати навичку до 75 рівня. Потребує джерела вогню та м'яса тварин." },
        [2565] = { [2] = "Збільшує ймовірність блокування щитом на {1}% протягом {2} с, але блокує лише [{1} атаку#block {1} attack.][{1} атаки#block {1} attacks.].#block by {1}% for {2} sec", [3] = "Ймовірність блокування збільшено на {1}% для наступної атаки.#increased by {1}%" },
        [2575] = { [2] = "Основи добування руди та каміння з мінеральних жил для використання в інженерії та ковальстві. Дозволяє розвивати навичку гірництва до 75 рівня. Для збору мінеральних жил необхідне кайло." },
        [2576] = { [2] = "Більш високий рівень гірництва. Дозволяє розвивати навичку гірництва до 150 рівня." },
        [2580] = { [2] = "На мінікарті з'являються мітки покладів мінералів неподалік. Одночасно можна відстежувати лише щось одне.", [3] = "Шукає мінерали." },
        [2589] = { [2] = "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", ["ref"] = 53 },
        [2590] = { [2] = "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", ["ref"] = 53 },
        [2591] = { [2] = "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", ["ref"] = 53 },
        [2597] = { [2] = "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", ["ref"] = 2370 },
        [2599] = { [2] = "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", ["ref"] = 2370 },
        [2600] = { [2] = "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", ["ref"] = 2370 },
        [2637] = { [2] = "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно лише одна ціль може бути змушена впасти в сплячку. Діє лише на звірів і драконів.#up to {1} sec", [3] = "Спить." },
        [2639] = { [2] = "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health and {2} mana over {3} sec", [3] = "Відновлює {1} здоров'я та {2} мани щосекунди.#Restores {1} health and {2} mana" },
