        [2645] = { [2] = "Перетворює шамана на примарного вовка, збільшуючи швидкість руху на {1}%. Можна використовувати лише просто неба.#speed by {1}%", [3] = "Збільшує швидкість руху на {1}%.#by {1}%" },
        [2649] = { [2] = "Провокує ціль, збільшуючи ймовірність того, що вона зосередить свої атаки на вас." },
        [2651] = { [2] = "Зменшує отриману шкоду від атак дального бою на {1} і збільшує ймовірність ухилення на {2}% протягом {3} с.#taken by {1}#dodge by {2}% for {3} sec", [3] = "Отриману шкоду від атак дального бою зменшено на {1}, а ймовірність ухилення збільшено на {2}%.#reduced by {1}#increased by {2}" },
        [2652] = { [2] = "Наступна атака ближнього бою проти заклинача завдасть {1} шкоди тінню та зменшить шкоду нападника на {2} протягом {3} хв.#cause {1}#by {2} for {3} min", [3] = "Наступна ворожа атака ближнього бою завдасть шкоди нападнику та послабить його." },
