        [7300] = { [2] = "Збільшує броню на {1}. Якщо ворог завдає удару заклиначеві, його рух може сповільнитися на {2}%, а інтервал між атаками збільшитися на {3}% протягом {4} с. Одночасно може бути активним лише один обладунок. Триває {5} хв.#Armor by {1}#slowed by {2}%#increased by {3}% for {4} sec#Lasts {5} min", [3] = "Збільшує броню на {1} та може сповільнити нападників.#Armor by {1}", ["ref"] = 168 },
