        [7302] = { [2] = "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", [3] = "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}" },
        [7320] = { [2] = "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", [3] = "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}", ["ref"] = 7302 },
        [7321] = { [3] = "Рух сповільнено на {1}%, а інтервал між атаками збільшено на {2}%.#slowed by {1}%#increased by {2}%", ["ref"] = 6136 },
        [7322] = { [2] = "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%", ["ref"] = 116 },
        [7328] = { [2] = "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana" },
        [7353] = { [2] = "Збільшує ваш дух на {1}.#Spirit by {1}", [3] = "Збільшує дух на {1}.#by {1}" },
        [7357] = { [2] = "Завдає ворогу {1} шкоди від природи кожні {2} с, збільшує інтервал між його атаками на {3}% і сповільнює його рух на на {4}% протягом {5} с.#Inflicts {1} Nature#every {2} sec#attacks by {3}%#movement by {4}% for {5} sec", [3] = "{1} шкоди від природи кожні {2} с.\nІнтервал між атаками збільшено на {3}%.\nШвидкість руху зменшено на {4}%.#{1} Nature#every {2} sec#attacks increased by {3}%#speed reduced by {4}%" },
        [7358] = { [2] = "Збільшує ваш дух на {1}.#Spirit by {1}", [3] = "Збільшує дух на {1}.#by {1}", ["ref"] = 7353 },
        [7363] = { [2] = "Збільшує дух учасників групи неподалік на {1}.#by {1}" },
        [7365] = { [2] = "Кидає у ворога пляшку з отрутою, що завдає {1} шкоди від природи кожні {2} с протягом {3} с.#inflicting {1} Nature#every {2} sec#for {3} sec", [3] = "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec" },
        [7367] = { [2] = "Завдає {1} шкоди від природи ворогу кожні {2} с та збільшує отриману ним фізичну шкоду на {3} протягом {4} хв.#Inflicts {1} Nature#every {2} sec#by {3} for {4} min", [3] = "Завдає {1} шкоди від природи кожні {2} с.\nОтриману фізичну шкоду збільшено на {3}.#{1} Nature#every {2} sec#increased by {3}" },
        [7369] = { [2] = "Розмашиста атака, що завдає шкоди зброєю плюс {1} по цілі та по найближчому до неї ворогу.#damage plus {1} to", ["ref"] = 845 },
        [7371] = { [2] = "Ривок у ворога, що знерухомлює його на {1} с і додає {2} сили атаки ближнього бою до наступної атаки кнура.#for {1} sec#adds {2} melee" },
        [7372] = { [2] = "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%", ["ref"] = 1715 },
        [7373] = { [2] = "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", [3] = "Швидкість руху зменшено на {1}%.#by {1}%", ["ref"] = 1715 },
        [7379] = { [2] = "Миттєва контратака, що завдає від {1} до {2} шкоди та значно збільшує рівень загрози. Помста повинна слідувати за блокуванням, ухиленням або парируванням.#for {1} to {2} damage", ["ref"] = 6572 },
        [7384] = { [2] = "Миттєво долає ворога, завдаючи шкоди зброєю плюс {1}. Можна використати лише після того, як ціль ухилилась. Здолання не можна блокувати, ухилитися від нього або парирувати.#damage plus {1}" },
        [7386] = { [2] = "Розколює броню цілі, зменшуючи її на {1} за кожен ефект \"Розколу броні\", та спричиняє високий рівень загрози. Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", [3] = "Броню зменшено на {1}.#decreased by {1}" },
        [7394] = { [2] = "Завдає навколишнім ворогам звичайної шкоди плюс {1}.#plus {1} to" },
        [7396] = { [2] = "Збільшує швидкість вашої атаки на {1}% протягом {2} с.#by {1}% for {2} sec", [3] = "Швидкість атаки збільшено." },
        [7400] = { [2] = "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", [3] = "Спровоковано.", ["ref"] = 694 },
        [7402] = { [2] = "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", [3] = "Спровоковано.", ["ref"] = 694 },
