        [7617] = { [2] = "З ймовірністю {1}% при отриманні удару в бою ви завдасте ворогу [{1}#inflicting {1} Shadow][від {1} до {2}#inflicting {1} to {2} Shadow] шкоди від тіні.#a {1}% chance of" },
        [7619] = { [2] = "З ймовірністю {1}% при отриманні удару в бою ви завдасте ворогу [{1}#inflicting {1} Shadow][від {1} до {2}#inflicting {1} to {2} Shadow] шкоди від тіні.#a {1}% chance of", ["ref"] = 7617 },
        [7620] = { [2] = "Візьміть до рук вудку і знайдіть водойму, в якій можна рибалити. Коли почуєте плескіт — клацніть на поплавок правою кнопкою миші, щоб витягнути впійману рибу. Чим вище ваша навичка риболовлі, тим більше шансів упіймати рибу у водоймах зон вищого рівня." },
        [7641] = { [2] = "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", ["ref"] = 686 },
        [7645] = { ["ref"] = 3442 },
        [7646] = { [2] = "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", [3] = "Фізичну шкоду зменшено на {1}.#by {1}", ["ref"] = 702 },
        [7648] = { [2] = "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", [3] = "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", ["ref"] = 172 },
        [7651] = { [2] = "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", [3] = "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", ["ref"] = 689 },
        [7658] = { [2] = "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", [3] = "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", ["ref"] = 704 },
        [7659] = { [2] = "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", [3] = "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", ["ref"] = 704 },
