        [11286] = { [2] = "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", [3] = "Недієздатність.", ["ref"] = 1776 },
