        [13159] = { [2] = "Мисливець і учасники групи в межах {1} м переймають аспекти зграї гепардів, збільшуючи швидкість руху на {2}%. Отримана шкода викличе в учасника зграї запаморочення на {3} с. Одночасно може бути активним лише один аспект.#within {1} y#speed by {2}%#for {3} sec", [3] = "Швидкість руху збільшено на {1}%. Запаморочення при отриманні шкоди.#{1}% increased" },
        [13161] = { [2] = "Мисливець переймає аспекти звіра, внаслідок чого його стає неможливо відстежити. Одночасно може бути активним лише один аспект.", [3] = "Неможливо відстежити." },
        [13163] = { [2] = "Мисливець переймає аспекти мавпи, збільшуючи ймовірність ухилення на {1}%. Одночасно може бути активним лише один аспект.#by {1}", [3] = "Збільшує ймовірність ухилення на {1}%.#by {1}" },
        [13165] = { [2] = "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", [3] = "Збільшує силу атаки дальнього бою на {1}.#by {1}" },
        [13180] = { [2] = "Вступити в ментальний бій з ціллю-гуманоїдом, щоб спробувати захопити контроль над її розумом. Якщо все пройде вдало, ви контролюватимете розум цілі протягом {1} секунд...#for {1} sec" },
        [13181] = { [3] = "Причаровано." },
        [13183] = { [2] = "Завдає [{1}#Deals {1} fire][від {1} до {2}#Deals {1} to {2} fire] шкоди вогнем протягом {1} с всім ворогам в конусі перед інженером. Це якщо вона не вибухне...#damage for {1} sec to all", [3] = "Завдає [{1}#Dealing {1} fire][від {1} до {2}#Dealing {1} to {2} fire] шкоди вогнем щосекунди." },
