        [13234] = { [2] = "Силовий щит захищає вас від наступних {1} од. шкоди протягом наступних {2} хв. УВАГА: Силове поле може перевантажитися при ударі, тимчасово запроторюючи власника в інший вимір.#next {1} damage#next {2} min", [3] = "Поглинає шкоду. Ефективність не гарантовано." },
        [13237] = { [2] = "Завдає від {1} до {2} шкоди вогнем та приголомшує цілі в радіусі {3} метрів на {4} с.#Inflicts {1} to {2} Fire#in a {3} yard#for {4} sec", [3] = "Приголомшено." },
        [13238] = { [2] = "Завдає від {1} до {2} шкоди вогнем та завдає {3} шкоди протягом {4} с цілям в радіусі {5} метрів.#Inflicts {1} to {2} Fire#causes {3} damage over {4} sec#in a {5} yard", [3] = "Приголомшено." },
        [13241] = { [2] = "При спрацюванні вибухає, завдаючи [{1}#triggered dealing {1} Fire damage][від {1} до {2}#triggered dealing {1} to {2} Fire damage] шкоди вогнем всім ворогам поблизу та [{1}#nearby and {1} damage to you][від {1} до {2}#nearby and {1} to {2} damage to you] шкоди вам." },
        [13262] = { [2] = "Вилучення магічних елементів зі зброї чи обладунків як мінімум високої якості (зелений колір назви). При цьому предмет БЕЗПОВОРОТНО ЗНИЩУЄТЬСЯ." },
