        [13322] = { [2] = "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", [3] = "Швидкість руху зменшено.", ["ref"] = 9672 },
        [13323] = { [2] = "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", [3] = "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено." },
        [13327] = { [2] = "Здійснити у ворога ривок, що робить його недієздатним на {1} секунд. Також збиває вас з ніг, приголомшуючи на короткий час. Будь-яка шкода повертає ціль до тями.#for {1} sec", [3] = "Недієздатність." },
