        [20154] = { [2] = "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.#for {1} sec#additional {2} to {3}", [3] = "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}" },
        [20162] = { [2] = "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", [3] = "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", ["ref"] = 21082 },
        [20164] = { [2] = "Наповнює паладина духом правосуддя на {1} с, надаючи кожній атаці ближнього бою ймовірність приголомшити ціль на {2} с. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, не дозволяючи йому втекти. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#justice for {1} sec#stun for {2} sec#enemy for {3} sec", [3] = "Атаки ближнього бою можуть приголомшити ціль на {1} с.#for {1} sec" },
        [20165] = { [2] = "Наповнює паладина божественним світлом на {1} с, надаючи кожній атаці ближнього бою ймовірність зцілити паладину {2} здоров'я. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам ближнього бою проти засудженої цілі ймовірність зцілити нападнику {4} здоров'я. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#light for {1} sec#heal the Paladin for {2}#enemy for {3} sec#attacker for {4}", [3] = "Атаки ближнього бою можуть відновити {1} здоров'я.#for {1}" },
        [20166] = { [2] = "Наповнює паладина божественною мудрістю на {1} с, надаючи кожній атаці ближнього бою ймовірність відновити паладину {2} мани. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам та закляттям проти засудженої цілі ймовірність відновити нападнику {4} мани. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#wisdom for {1} sec#restore {2} of the Paladin#enemy for {3} sec#restore {4} mana to the attacker", [3] = "Атаки ближнього бою можуть відновити {1} мани.#restore {1} mana" },
