        [20905] = { [2] = "Збільшує силу атаки[ дальнього бою#the ranged attack power of party] учасників групи в межах {1} м на {2}[, а силу атаки дальнього бою мисливця додатково на {1}#ranged attack power by an additional {1}]. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", [3] = "Силу атаки[ дальнього бою#Ranged Attack Power increased by {1}] збільшено на {1}[, а силу атаки дальнього бою мисливця додатково на {1}#Ranged Attack Power increased by an additional {1}].#increased by {1}", ["ref"] = 19506 },
        [20906] = { [2] = "Збільшує силу атаки[ дальнього бою#the ranged attack power of party] учасників групи в межах {1} м на {2}[, а силу атаки дальнього бою мисливця додатково на {1}#ranged attack power by an additional {1}]. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", [3] = "Силу атаки[ дальнього бою#Ranged Attack Power increased by {1}] збільшено на {1}[, а силу атаки дальнього бою мисливця додатково на {1}#Ranged Attack Power increased by an additional {1}].#increased by {1}", ["ref"] = 19506 },
        [20909] = { [2] = "Удар, який можливо провести лише після парирування атаки опонента. Ця атака завдає {1} шкоди та знерухомлює ціль на {2} с. Контратаку неможливо блокувати, парирувати чи ухилитися від неї.#deals {1} damage#for {2} sec", [3] = "Знерухомлено.", ["ref"] = 19306 },
        [20910] = { [2] = "Удар, який можливо провести лише після парирування атаки опонента. Ця атака завдає {1} шкоди та знерухомлює ціль на {2} с. Контратаку неможливо блокувати, парирувати чи ухилитися від неї.#deals {1} damage#for {2} sec", [3] = "Знерухомлено.", ["ref"] = 19306 },
        [20911] = { [2] = "Благословляє дружню ціль, зменшуючи отриману нею шкоду з усіх джерел на {1} протягом {2} хв. Додатково, коли ціль блокує атаку ближнього бою, нападнику буде завдано {3} шкоди святістю. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#to {1} for {2} min#will take {3}", [3] = "Отриману шкоду зменшено на {1}, а заблоковані атаки ближнього бою завдають {2} шкоди святістю нападнику.#up to {1}#cause {2}" },
        [20912] = { ["ref"] = 20911 },
