        [20989] = { [2] = "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", [3] = "Спить.", ["ref"] = 12098 },
        [21007] = { [2] = "Зменшує завдану навколишніми ворогами фізичну шкоду на {1} протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", [3] = "Завдану фізичну шкоду зменшено на {1}.#by {1}", ["ref"] = 12741 },
