        [21047] = { [2] = "Завдає ворогу шкоди від природи і зменшує його броню протягом {1} с.#for {1} sec", [3] = "Броню зменшено.", ["ref"] = 19463 },
        [21055] = { [2] = "Б'є по броні ворога, зменшуючи її на {1} за кожен ефект \"Дроблення броні\". Може накопичуватись до {2} разів. Триває {3} с.#it by {1} per#up to {2} times#Lasts {3} sec", [3] = "Броню зменшено." },
        [21056] = { [3] = "Висмоктує {1} мани кожні {2} с.\nВибухає, якщо не може висмоктати ману.#Drains {1} mana every {2} sec" },
        [21060] = { [2] = "Засліплює ціль, змушуючи її блукати протягом {1} с. Будь-яка шкода перериває дію ефекту.#for up to {1} sec", [3] = "Дезорієнтовано." },
        [21063] = { [3] = "При отриманні шкоди зцілює нападнику {1} здоров'я.#for {1}" },
        [21067] = { [2] = "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", [3] = "Завдає шкоди від природи кожні {1} с.#every {1} sec" },
