        [21069] = { ["ref"] = 17197 },
        [21072] = { [2] = "Завдає шкоди від вогню ворогу.", ["ref"] = 9053 },
        [21081] = { [2] = "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", [3] = "Броню зменшено.", ["ref"] = 11971 },
        [21082] = { [2] = "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", [3] = "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster" },
        [21084] = { [2] = "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові {4} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4}", [3] = "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}" },
        [21098] = { [2] = "Вражає навколишніх ворогів льодом, завдаючи від {1} до {2} шкоди, збільшуючи інтервал між атаками на {3}% та зменшуючи швидкість руху на {4}%.#dealing {1} to {2} damage#attacks by {3}%#speed by {4}%", [3] = "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%" },
        [21099] = { [2] = "Завдає шкоди від криги ворогам у конусі перед заклиначем, викрадаючи у них ману і зменшуючи швидкість руху на {1} с.#speed for {1} sec", [3] = "Швидкість руху зменшено.", ["ref"] = 16094 },
        [21109] = { [2] = "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", [3] = "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", ["ref"] = 20885 },
        [21140] = { [2] = "Завдає смертельної рани на [{1}#for {1} damage][{1}-{2}#for {1} to {2} damage] шкоди.", ["ref"] = 16411 },
        [21141] = { [2] = "Випускає у ворога тіньову стрілу, що завдає {1} шкоди тінню і додатково {2} шкоди кожні {3} с протягом {4} с.#causing {1} Shadow#dealing {2} damage every {3} sec for {4} sec", [3] = "{1} шкоди від тіні кожні {2} с.#Deals {1} Shadow#every {2} sec", ["ref"] = 17483 },
        [21142] = { [2] = "Завдає {1} шкоди від вогню всім, хто атакує вас у ближньому бою.#Deals {1} Fire", ["ref"] = 4436 },
        [21149] = { [2] = "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв. А ще він трішки п'янить...#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", [3] = "Відновлює {1} здоров'я щосекунди.#Restores {1} health" },
        [21151] = { [2] = "Випускає у ворога тіньову стрілу, що завдає {1} шкоди від тіні та зменшує всі характеристика на {2} протягом {3} с..#causing {1} Shadow damage and lowering all stats by {2} for {3} sec" },
