        [21971] = { [2] = "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", [3] = "Завдає шкоди від природи кожні {1} с.#every {1} sec", ["ref"] = 21067 },
