        [21989] = { },
        [21992] = { [2] = "Вражає ворога блискавкою, що завдає {1} шкоди від природи, а потім стрибає на інших ворогів, що знаходяться поруч. Кожен стрибок зменшує опір силам природи жертви на {2}. Вражає до {3} цілей. Ваша основна ціль також поглинається циклоном, що зменшує швидкість її атаки на {4}% протягом {5} с.#dealing {1} Nature#resistance by {2}.#Affects {3} targets#speed by {4}% for {5} sec", [3] = "Опір природі зменшено на {1}.#reduced by {1}" },
