        [25289] = { [2] = "Воїн кричить, збільшуючи силу атаки ближнього бою всіх учасників групи в межах {1} м на {2}. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", [3] = "Збільшує силу атаки ближнього бою на {1}.#power by {1}", ["ref"] = 5242 },
