        [27780] = { [2] = "При отриманні удару в бою ви можете налякати нападника, змушуючи його втікати протягом 2 секунд." },
        [27789] = { [2] = "Збільшує дальність дії ваших заклять \"Кара\" та \"Священний вогонь\", а також радіус дії ваших заклять \"Молитва зцілення\" та \"Священний спалах\" на {1}%.#by {1}%" },
        [27790] = { ["ref"] = 27789 },
        [27794] = { [2] = "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", ["ref"] = 11427 },
        [27799] = { [2] = "Створює вибух священного світла навколо заклинача, завдаючи від {1} до {2} шкоди святістю ворожим цілям в радіусі {3} м і зцілюючи від {5} до {6} здоров'я учасникам групи в межах {4} м. Ці ефекти не спричиняють загрози.#causing {1} to {2} Holy#targets within {3} y#members within {4} yards for {5} to {6}", ["ref"] = 15237 },
