        [31016] = { [2] = "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", ["ref"] = 2098 },
        [31018] = { [2] = "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", ["ref"] = 22568 },
        [31700] = { [2] = "Викликає та відпускає верхового кіразького бойового танка. Це дуже швидка верхова тварина.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%", ["ref"] = 25863 },
        [43680] = { [2] = "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", [3] = "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі." },
        [43681] = { [2] = "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", [3] = "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою." },
        [219003] = { [2] = "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", [3] = "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", ["ref"] = 43680 },
        [219004] = { [2] = "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", [3] = "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою." },
        [301089] = { [2] = "Несе прапор Орди. Принесіть прапор на свою базу, щоб захопити його.", [3] = "Несе прапор Орди. Принесіть прапор на свою базу, щоб захопити його." },
