        [369330] = { [2] = "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи від {1} до {2} шкоди вогнем кожні {3} с протягом {4} с.#for {1} to {2} Fire#every {3} sec#for {4} sec", [3] = "Отримання від {1} до {2} шкоди від вогню кожні {3} с.#{1} to {2} Fire#every {3} sec", ["ref"] = 28794 },
        [370637] = { [2] = "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [370831] = { [2] = "Прикріпити блискавичники на шию, щоб випадковим чином отримати позитивний або негативний заряд, що збільшує шкоду та зцілення на 1%. \n\nЦей ефект посилюється, якщо ви перебуваєте поруч із союзниками, які мають такий самий заряд, і завдає шкоди від природи союзникам, які мають протилежний заряд.", [3] = "Приборкання сили блискавки." },
        [370832] = { [2] = "Проткнути себе іклом, щоб збільшити швидкість руху, швидкість атаки та швидкість вимови заклять на 15% протягом 1 год.", [3] = "Швидкість руху, швидкість атаки і швидкість вимови заклять збільшено на {1}%.\n\nВи почуваєтеся тривожно...#by {1}%" },
        [371656] = { [3] = "Швидкість руху збільшено на {1}%.#by {1}%" },
        [381598] = { [2] = "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%", ["ref"] = 370637 },
        [381599] = { [2] = "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", [3] = "Швидкість руху збільшено на {1}%.#by {1}%", ["ref"] = 370637 },
        [422621] = { [2] = "Зменшує витрати ресурсів закляттями та здібностями на {1}%.#by {1}%", [3] = "Зменшує витрати ресурсів закляттями та здібностями на {1}%.#by {1}%" },
        [1225295] = { [2] = "Збільшує ймовірність влучити на {1}%.#hit by {1}%" },
        [1229451] = { [2] = "Нещодавно ви відпочивали в табірному наметі. Протягом 1 год. повторно отримати його перевагу не можна.", [3] = "Нещодавно ви відпочивали в табірному наметі. Протягом 1 год. повторно отримати його перевагу не можна." },
        [1229739] = { [2] = "Надає різні переваги табору після 1 хв сидіння біля багаття залежно від додаткових табірних об’єктів, розміщених поруч.", [3] = "Надає різні переваги табору після 1 хв сидіння біля багаття залежно від додаткових табірних об’єктів, розміщених поруч.", ["aura_lines"] = { ["Grants various camp benefits after 1 min spent sitting near the campfire, based on what additional camp objects are placed near the campfire."] = "Надає різні переваги табору після 1 хв сидіння біля багаття залежно від додаткових табірних об’єктів, розміщених поруч.", ["Grants various camp benefits after 1 min spent sitting near the campfire. You may also craft using tradeskills, as long as you do not move."] = "Надає різні переваги табору після 1 хв сидіння біля багаття. Також можна займатися ремеслом, якщо не рухатися." }, ["aura_patterns"] = { [1] = { [1] = "^(%d+) seconds remaining$", [2] = "Залишилося %s с" }, [2] = { [1] = "^(%d+) second remaining$", [2] = "Залишилася %s с" }, [3] = { [1] = "^(%d+) minutes remaining$", [2] = "Залишилося %s хв" }, [4] = { [1] = "^(%d+) minute remaining$", [2] = "Залишилася %s хв" } } },
        [1229741] = { [2] = "Отримано такі переваги табору:\n\nНамет: ви отримали невелику кількість досвіду відпочинку. Цей ефект можна отримати лише раз на годину.", [3] = "Отримано такі переваги табору:\n\nНамет: ви отримали невелику кількість досвіду відпочинку. Цей ефект можна отримати лише раз на годину.", ["aura_lines"] = { ["Gained the following camp benefits:"] = "Отримано такі переваги табору:", ["Tent: You received a small amount of rest experience. You can only receive this effect once per 1 hour."] = "Намет: ви отримали невелику кількість досвіду відпочинку. Цей ефект можна отримати лише раз на годину." }, ["aura_patterns"] = { [1] = { [1] = "^First Aid Kit: Stamina increased by (%d+)%.?$", [2] = "Аптечка першої допомоги: витривалість збільшено на %s." }, [2] = { [1] = "^Sharpening Wheel: Strength increased by (%d+)%.?$", [2] = "Заточувальне колесо: силу збільшено на %s." }, [3] = { [1] = "^Fish Bowl: All stats increased by (%d+)%%%.?$", [2] = "Акваріум: усі характеристики збільшено на %s%%." }, [4] = { [1] = "^Lodestone: Melee Attack Power increased by (%d+)%.?$", [2] = "Магнітяк: силу атаки ближнього бою збільшено на %s." } } },
        [1230117] = { ["tooltip_lines"] = { ["Use: Unpacks a first aid kit that allows you and others sitting nearby to gain 3 increased Stamina, exclusive with Power Word: Fortitude.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour."] = "Використання: розкладає аптечку першої допомоги, що дає вам та іншим персонажам, які сидять поруч, 3 од. витривалості. Не поєднується зі «Словом сили: Стійкість».\r\n\r\nПоруч має бути багаття. Усі табірні можливості мають спільний час відновлення — 1 год." } },
        [1230161] = { [2] = "Створити Магнітняк." },
        [1230656] = { [2] = "Створює реагентного бота." },
        [1248805] = { ["tooltip_lines"] = { ["Permanently enchant a Melee Weapon to have a chance to trigger Revelation when a non-periodic spell fails to critically strike. Revelation grants 100% increased critical strike chance to the next spell cast. Revelation's chance to trigger is diminished as your critical strike chance increases."] = "Назавжди зачаровує зброю ближнього бою, надаючи шанс активувати Одкровення, коли неперіодичне закляття не завдає критичного удару. Одкровення збільшує шанс критичного удару наступного застосованого закляття на 100%. Шанс активації Одкровення зменшується зі зростанням вашого шансу критичного удару.", ["Tools: Runed Silver Rod"] = "Інструменти: рунічний срібний жезл" } },
        [1249519] = { [3] = "Силу атаки збільшено на {1}. Досвід за вбивства збільшено на 5%.#by {1}", ["aura_lines"] = { ["Your Attack Power is increased by 10. Experience gained from kills increased by 5%."] = "Силу атаки збільшено на 10. Досвід за вбивства збільшено на 5%." }, ["aura_patterns"] = { [1] = { [1] = "^Your Attack Power is increased by (%d+)%. Experience gained from kills increased by 5%%%.?$", [2] = "Силу атаки збільшено на %s. Досвід за вбивства збільшено на 5%%." } } },
        [1259705] = { [2] = "Ви намагаєтеся скористатися силою найближчої лей-лінії, збільшуючи швидкість відновлення здоров’я та мани на 100%. Діє 15 с, якщо поблизу немає лей-лінії, і 15 хв, якщо її знайдено." },
        [1259719] = { [2] = "Збільшує шанс критичного удару всіма закляттями та атаками на 1%, коли ви тримаєте булаву або дворучну булаву." },
        [1259721] = { [2] = "Шкоду звірам збільшено на 5%.", [3] = "Шкоду звірам збільшено на 5%." },
        [1259817] = { ["tooltip_lines"] = { ["2 min cooldown"] = "Відновлення: 2 хв", ["Your next 3 damaging abilities have their Mana cost reduced by 10% and deal 10% more damage."] = "Ваші наступні 3 здібності, що завдають шкоди, витрачають на 10% менше мани та завдають на 10% більше шкоди." } },
        [1283391] = { [2] = "Приємний дим багаття долинає звідкись неподалік.", [3] = "Приємний дим багаття долинає звідкись неподалік." },
        [1289682] = { [2] = "Атаки ближнього бою основною рукою по ворогах під дією вашого «Розриву» з ймовірністю {1}% дають змогу застосувати до цілі «Здолання». Триває {2} с.#have a {1}% chance#Lasts {2}" },
        [1289723] = { [2] = "Надає різні переваги табору, якщо сидіти біля багаття протягом 1 хв. Також можна займатися ремеслом, якщо не рухатися.", [3] = "Надає різні переваги табору, якщо сидіти біля багаття протягом 1 хв. Також можна займатися ремеслом, якщо не рухатися.", ["aura_lines"] = { ["Grants various camp benefits after 1 min spent sitting near the campfire, based on what additional camp objects are placed near the campfire."] = "Надає різні переваги табору після 1 хв сидіння біля багаття залежно від додаткових табірних об’єктів, розміщених поруч.", ["Grants various camp benefits after 1 min spent sitting near the campfire. You may also craft using tradeskills, as long as you do not move."] = "Надає різні переваги табору після 1 хв сидіння біля багаття. Також можна займатися ремеслом, якщо не рухатися." }, ["aura_patterns"] = { [1] = { [1] = "^(%d+) seconds remaining$", [2] = "Залишилося %s с" }, [2] = { [1] = "^(%d+) second remaining$", [2] = "Залишилася %s с" }, [3] = { [1] = "^(%d+) minutes remaining$", [2] = "Залишилося %s хв" }, [4] = { [1] = "^(%d+) minute remaining$", [2] = "Залишилася %s хв" } } },
        [1290261] = { [2] = "Атаки зброєю ближнього бою отримують бонус залежно від зброї.|n|n|CFFFFFFFFСокира/держакова зброя:|R збільшує ймовірність критичного удару на {1}%.|n|CFFFFFFFFБулава/посох:|R атаки ігнорують {2}% броні цілі.|n|CFFFFFFFFМеч:|R успішні атаки ближнього бою з ймовірністю {3}% спричиняють додаткову атаку по цілі.#critical strike chance by {1}%#{2}% of your target's armor#attacks have a {3}% chance" },
        [1293657] = { ["tooltip_lines"] = { ["You are fluent in the following languages:\r\nCommon\r\nGnomish"] = "Ви володієте такими мовами:\r\nЗагальна\r\nГномська" } },
        [1293712] = { [2] = "Ви вмієте носити такі види обладунків:\r\nТканинні\r\nШкіряні\r\nКольчужні" },
        [1310222] = { [2] = "Жорстокий удар, що завдає {1}% шкоди зброєю. Велетням, драконідам і вершникам завдає додатково {2}% шкоди зброєю. Вершників збиває з сідла.#deals {1}% weapon damage#additional {2}% weapon damage" },
        [1310236] = { [2] = "Збільшує максимальний запас люті на {1}.#maximum Rage by {1}" },
        [1310315] = { [2] = "«Вихор» також завдає удару зброєю з другої руки, а витрати люті на «Розсічення» зменшуються на {1}.#Cleave ability by {1}" },
        [1310316] = { [2] = "Дає {1}% ймовірності отримати {2} од. люті під час ухилення або парирування зі щитом у руках.#a {1}% chance to generate {2} Rage" },
        [1310317] = { [2] = "«Ривок» тепер можна застосовувати в захисній стійці." },
    },
